    92→    public function conflictCheck(Request $request)
    93→    {
    94→        $request->validate([
    95→            'tanggal'            => 'required|date',
    96→            'jam_mulai'          => 'required',
    97→            'jam_selesai'        => 'required',
    98→            'guru_id'            => 'nullable|exists:teachers,id',
    99→            'ruangan'            => 'nullable|string',
   100→            'cabang_id'          => 'nullable|exists:branches,id',
   101→            'exclude_id'         => 'nullable|exists:schedules,id',
   102→        ]);
   103→
   104→        $result = ['room' => null, 'teacher' => null, 'busy_teacher_ids' => [], 'has_conflict' => false];
   105→
   106→        $overlapQuery = function ($q) use ($request) {
   107→            $q->where(function ($inner) use ($request) {
   108→                $inner->whereBetween('jam_mulai', [$request->jam_mulai, $request->jam_selesai])
   109→                      ->orWhereBetween('jam_selesai', [$request->jam_mulai, $request->jam_selesai])
   110→                      ->orWhere(function ($i2) use ($request) {
   111→                          $i2->where('jam_mulai', '<=', $request->jam_mulai)
   112→                             ->where('jam_selesai', '>=', $request->jam_selesai);
   113→                      });
   114→            });
   115→        };
   116→
   117→        if ($request->filled('ruangan') && $request->filled('cabang_id')) {
   118→            $roomConflict = Schedule::where('tanggal', $request->tanggal)
   119→                ->where('ruangan', $request->ruangan)
   120→                ->where('cabang_id', $request->cabang_id)
   121→                ->where('status', '!=', 'dibatalkan')
   122→                ->when($request->exclude_id, fn($q) => $q->where('id', '!=', $request->exclude_id))
   123→                ->where($overlapQuery)
   124→                ->with(['paket', 'guru'])
   125→                ->first();
   126→
   127→            $result['room'] = $roomConflict
   128→                ? ['conflict' => true, 'detail' => "Ruangan \"{$request->ruangan}\" sudah dipakai: {$roomConflict->paket?->nama} — Guru: {$roomConflict->guru?->name} ({$roomConflict->jam_mulai}–{$roomConflict->jam_selesai})"]
   129→                : ['conflict' => false, 'detail' => "Ruangan \"{$request->ruangan}\" tersedia di waktu ini."];
   130→        }
   131→
   132→        if ($request->filled('guru_id')) {
   133→            $teacherConflict = Schedule::where('tanggal', $request->tanggal)
   134→                ->where('guru_id', $request->guru_id)
   135→                ->where('status', '!=', 'dibatalkan')
   136→                ->when($request->exclude_id, fn($q) => $q->where('id', '!=', $request->exclude_id))
   137→                ->where($overlapQuery)
   138→                ->with('paket')
   139→                ->first();
   140→
   141→            $result['teacher'] = $teacherConflict
   142→                ? ['conflict' => true, 'detail' => "Guru sedang mengajar: {$teacherConflict->paket?->nama} ({$teacherConflict->jam_mulai}–{$teacherConflict->jam_selesai})"]
   143→                : ['conflict' => false, 'detail' => 'Guru tersedia di waktu ini.'];
   144→        }
   145→
   146→        $busyIds = Schedule::where('tanggal', $request->tanggal)
   147→            ->where('status', '!=', 'dibatalkan')
   148→            ->when($request->exclude_id, fn($q) => $q->where('id', '!=', $request->exclude_id))
   149→            ->where($overlapQuery)
   150→            ->whereNotNull('guru_id')
   151→            ->pluck('guru_id')
   152→            ->unique()
   153→            ->values()
   154→            ->toArray();
   155→        $result['busy_teacher_ids'] = $busyIds;
   156→
   157→        $result['has_conflict'] = ($result['room']['conflict'] ?? false) || ($result['teacher']['conflict'] ?? false);
   158→
   159→        return response()->json(['success' => true, 'data' => $result]);
   160→    }
