   469→async function runConflictCheck() {
   470→    const btn = document.getElementById('btnCekKonflik');
   471→    btn.disabled = true;
   472→    btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span>Memeriksa konflik...';
   473→
   474→    const jenis    = document.getElementById('jenis').value;
   475→    const ruangan  = jenis === 'offline' ? (document.getElementById('ruangan').value || '') : '';
   476→    const cabangId = currentPaket?.cabang_id || '';
   477→
   478→    const payload = new FormData();
   479→    payload.append('_token', csrf);
   480→    payload.append('tanggal',     document.getElementById('tanggal').value);
   481→    payload.append('jam_mulai',   document.getElementById('jam_mulai').value);
   482→    payload.append('jam_selesai', document.getElementById('jam_selesai').value);
   483→    payload.append('ruangan',     ruangan);
   484→    payload.append('cabang_id',   cabangId);
   485→
   486→    try {
   487→        const res  = await fetch(conflictCheckUrl, { method: 'POST', body: payload });
   488→        if (!res.ok) throw new Error('HTTP ' + res.status);
   489→        const json = await res.json();
   490→        const data = json.data || {};
   491→
   492→        busyTeacherIds = data.busy_teacher_ids || [];
   493→        renderKonflikResults(data, jenis, ruangan);
   494→        // Re-render guru list to reflect busy status
   495→        if (currentPaket) renderGuruList();
   496→    } catch (err) {
   497→        showToast('Gagal menghubungi server. Coba lagi.', 'error');
   498→    } finally {
   499→        btn.disabled = false;
   500→        btn.innerHTML = '<i class="bi bi-shield-check me-2"></i>Cek Konflik Sekarang';
   501→    }
   502→}
