   565→function renderGuruList() {
   566→    if (!currentPaket) return;
   567→    const mapelId = currentMapelId ? parseInt(currentMapelId) : null;
   568→
   569→    let pkgTeacherIds = [];
   570→    if (mapelId && currentPaket.course_teachers) {
   571→        const ct = currentPaket.course_teachers[mapelId];
   572→        if (ct && ct.length > 0) pkgTeacherIds = ct.map(Number);
   573→    }
   574→
   575→    let preferred = [], others = [];
   576→    teachers.forEach(t => {
   577→        const isPref = pkgTeacherIds.length > 0
   578→            ? pkgTeacherIds.includes(t.id)
   579→            : (mapelId ? t.course_ids.includes(mapelId) : false);
   580→        if (isPref) preferred.push(t); else others.push(t);
   581→    });
   582→
   583→    let html = '';
   584→    if (preferred.length > 0) {
   585→        html += `<div class="col-12 mb-1"><div class="text-muted fw-semibold" style="font-size:11px;text-transform:uppercase;letter-spacing:.5px">✅ Guru sesuai mata pelajaran (${preferred.length})</div></div>`;
   586→        preferred.forEach(t => { html += renderGuruCard(t, true); });
   587→    }
